    jwt_t* jwt = NULL;

    // Decode JWT
    int ret = jwt_decode(&jwt, token, NULL, 0);
    if (ret != 0) {
        return strdup("{}");
    }

    // Get claims as JSON string
    char* claims = jwt_get_grants_json(jwt, NULL);
    if (!claims) {
